mapper.select:
SELECT DISTINCT B.ACCT_NO as acctNo, B.BUSI_ACCT_NO busiAcctNo, B.CCY CCY, A.ACCT_TYPE acctType, B.ACCT_NAME as acctName, B.OWN_DEPT stockExchangeNo, '1' status, B.ACC_PASS acctPwd, B.TRADE_PASS tradePwd FROM MST_COUNTER_ACCT A, STL_CAPACCT_INFO B
A.COUNTER_ID = #{counterId,jdbcType=VARCHAR}
and A.ACCT_TYPE =#{acctType,jdbcType=VARCHAR}
AND A.ACCT_NO = B.ACCT_NO AND A.IS_OPEN = '01' /**add by 张年 20190904 交易对手资金账户只能选择启用状态下的账户**/ AND A.CCY = B.CCY
AND A.CCY = #{ccy,jdbcType=VARCHAR}
